#pragma once
#include <memory>
#include <string>
#include <vector>

namespace inst {

struct Market { 
    double spot, rate, vol; 
};

class Instrument {
public:
    virtual ~Instrument() = default;
    virtual void accept(class Visitor&) const = 0;
    virtual std::unique_ptr<Instrument> clone() const = 0;
};

class Visitor {
public:
    virtual ~Visitor() = default;
};

struct Position {
    std::unique_ptr<Instrument> item;
    double quantity;
};

class EuropeanOption : public Instrument {
private:
    double strike_;
    double maturity_;
    bool is_call_;

public:
    EuropeanOption(double strike, double maturity, bool is_call);

    double strike() const { return strike_; }
    double maturity() const { return maturity_; }
    bool is_call() const { return is_call_; }

    void accept(Visitor&) const override;
    std::unique_ptr<Instrument> clone() const override;
};

class DigitalOption : public Instrument {
private:
    double strike_;
    double maturity_;
    double cash_;

public:
    DigitalOption(double strike, double maturity, double cash);

    double strike() const { return strike_; }
    double maturity() const { return maturity_; }
    double cash() const { return cash_; }

    void accept(Visitor&) const override;
    std::unique_ptr<Instrument> clone() const override;
};

class BarrierOption : public Instrument {
private:
    double strike_;
    double barrier_;
    double maturity_;

public:
    BarrierOption(double strike, double barrier, double maturity);

    double strike() const { return strike_; }
    double barrier() const { return barrier_; }
    double maturity() const { return maturity_; }

    void accept(Visitor&) const override;
    std::unique_ptr<Instrument> clone() const override;
};

class ZeroCouponBond : public Instrument {
private:
    double maturity_;
    double notional_;

public:
    ZeroCouponBond(double maturity, double notional);

    double maturity() const { return maturity_; }
    double notional() const { return notional_; }

    void accept(Visitor&) const override;
    std::unique_ptr<Instrument> clone() const override;
};

class Portfolio : public Instrument {
private:
    std::vector<Position> positions_;

public:
    void add(std::unique_ptr<Instrument> item, double quantity);
    std::size_t size() const { return positions_.size(); }
    const std::vector<Position>& positions() const { return positions_; }

    void accept(Visitor&) const override;
    std::unique_ptr<Instrument> clone() const override;
};

class PricingVisitor : public Visitor {
private:
    Market market_;
    double result_;

public:
    explicit PricingVisitor(Market m);
    double result() const { return result_; }

    void visit(const EuropeanOption&);
    void visit(const DigitalOption&);
    void visit(const BarrierOption&);
    void visit(const ZeroCouponBond&);
    void visit(const Portfolio&);
};

class DeltaVisitor : public Visitor {
private:
    Market market_;
    double result_;

public:
    explicit DeltaVisitor(Market m);
    double result() const { return result_; }

    void visit(const EuropeanOption&);
    void visit(const DigitalOption&);
    void visit(const BarrierOption&);
    void visit(const ZeroCouponBond&);
    void visit(const Portfolio&);
};

class JsonVisitor : public Visitor {
private:
    std::string result_;

public:
    std::string result() const { return result_; }

    void visit(const EuropeanOption&);
    void visit(const DigitalOption&);
    void visit(const BarrierOption&);
    void visit(const ZeroCouponBond&);
    void visit(const Portfolio&);
};

} // namespace inst

