#include "instruments.hpp"
#include <cmath>
#include <sstream>
#include <iomanip>

namespace inst {

// Helper function for normal CDF
inline double norm_cdf(double x) {
    return 0.5 * (1.0 + std::erf(x / std::sqrt(2.0)));
}

// Helper function for normal PDF
inline double norm_pdf(double x) {
    return (1.0 / std::sqrt(2.0 * M_PI)) * std::exp(-0.5 * x * x);
}

// EuropeanOption implementation
EuropeanOption::EuropeanOption(double strike, double maturity, bool is_call)
    : strike_(strike), maturity_(maturity), is_call_(is_call) {}

void EuropeanOption::accept(Visitor& v) const {
    v.visit(*this);
}

std::unique_ptr<Instrument> EuropeanOption::clone() const {
    return std::make_unique<EuropeanOption>(*this);
}

// DigitalOption implementation
DigitalOption::DigitalOption(double strike, double maturity, double cash)
    : strike_(strike), maturity_(maturity), cash_(cash) {}

void DigitalOption::accept(Visitor& v) const {
    v.visit(*this);
}

std::unique_ptr<Instrument> DigitalOption::clone() const {
    return std::make_unique<DigitalOption>(*this);
}

// BarrierOption implementation
BarrierOption::BarrierOption(double strike, double barrier, double maturity)
    : strike_(strike), barrier_(barrier), maturity_(maturity) {}

void BarrierOption::accept(Visitor& v) const {
    v.visit(*this);
}

std::unique_ptr<Instrument> BarrierOption::clone() const {
    return std::make_unique<BarrierOption>(*this);
}

// ZeroCouponBond implementation
ZeroCouponBond::ZeroCouponBond(double maturity, double notional)
    : maturity_(maturity), notional_(notional) {}

void ZeroCouponBond::accept(Visitor& v) const {
    v.visit(*this);
}

std::unique_ptr<Instrument> ZeroCouponBond::clone() const {
    return std::make_unique<ZeroCouponBond>(*this);
}

// Portfolio implementation
void Portfolio::add(std::unique_ptr<Instrument> item, double quantity) {
    positions_.push_back({std::move(item), quantity});
}

void Portfolio::accept(Visitor& v) const {
    v.visit(*this);
}

std::unique_ptr<Instrument> Portfolio::clone() const {
    auto clone = std::make_unique<Portfolio>();
    for (const auto& pos : positions_) {
        clone->add(pos.item->clone(), pos.quantity);
    }
    return clone;
}

// PricingVisitor implementation
PricingVisitor::PricingVisitor(Market m) : market_(m), result_(0.0) {}

void PricingVisitor::visit(const EuropeanOption& option) {
    double S = market_.spot;
    double K = option.strike();
    double T = option.maturity();
    double r = market_.rate;
    double sigma = market_.vol;

    double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    double d2 = d1 - sigma * std::sqrt(T);

    if (option.is_call()) {
        result_ = S * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d2);
    } else {
        result_ = K * std::exp(-r * T) * norm_cdf(-d2) - S * norm_cdf(-d1);
    }
}

void PricingVisitor::visit(const DigitalOption& option) {
    double S = market_.spot;
    double K = option.strike();
    double T = option.maturity();
    double r = market_.rate;
    double sigma = market_.vol;

    double d2 = (std::log(S / K) + (r - 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));

    result_ = option.cash() * std::exp(-r * T) * norm_cdf(d2);
}

void PricingVisitor::visit(const BarrierOption& option) {
    double S = market_.spot;
    double K = option.strike();
    double B = option.barrier();
    double T = option.maturity();
    double r = market_.rate;
    double sigma = market_.vol;

    // Rubinstein-Reiner formula for down-and-out call
    // Simplified version for the case where barrier < spot and barrier <= strike
    double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    double d2 = d1 - sigma * std::sqrt(T);
    double d3 = (std::log(S / B) + (r + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    double d4 = d3 - sigma * std::sqrt(T);

    double call_price = S * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d2);
    double knock_out = S * std::exp(-r * T) * (std::pow(B / S, 2 * (r + 0.5 * sigma * sigma) / (sigma * sigma)) * norm_cdf(d3) - 
                                              std::pow(B / S, 2 * (r + 0.5 * sigma * sigma) / (sigma * sigma) - 2) * norm_cdf(d4));

    result_ = call_price - knock_out;
}

void PricingVisitor::visit(const ZeroCouponBond& bond) {
    double T = bond.maturity();
    double r = market_.rate;

    result_ = bond.notional() * std::exp(-r * T);
}

void PricingVisitor::visit(const Portfolio& portfolio) {
    double total = 0.0;
    for (const auto& pos : portfolio.positions()) {
        // Create a temporary visitor to calculate the value of each position
        PricingVisitor temp_visitor(market_);
        pos.item->accept(temp_visitor);
        total += temp_visitor.result() * pos.quantity;
    }
    result_ = total;
}

// DeltaVisitor implementation
DeltaVisitor::DeltaVisitor(Market m) : market_(m), result_(0.0) {}

void DeltaVisitor::visit(const EuropeanOption& option) {
    double S = market_.spot;
    double K = option.strike();
    double T = option.maturity();
    double r = market_.rate;
    double sigma = market_.vol;

    double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));

    if (option.is_call()) {
        result_ = norm_cdf(d1);
    } else {
        result_ = norm_cdf(d1) - 1.0;
    }
}

void DeltaVisitor::visit(const DigitalOption& option) {
    double S = market_.spot;
    double K = option.strike();
    double T = option.maturity();
    double r = market_.rate;
    double sigma = market_.vol;

    double d2 = (std::log(S / K) + (r - 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));

    result_ = option.cash() * std::exp(-r * T) * norm_pdf(d2) / (S * sigma * std::sqrt(T));
}

void DeltaVisitor::visit(const BarrierOption& option) {
    // For simplicity, we'll use a numerical approximation for barrier option delta
    // This is a simplified approach - in practice, more complex formulas would be used
    double eps = 1e-5;
    double original = 0.0;
    double bumped = 0.0;

    // Create two market conditions with slightly different spot prices
    Market bumped_market = market_;
    bumped_market.spot += eps;

    PricingVisitor original_visitor(market_);
    PricingVisitor bumped_visitor(bumped_market);

    // We'll approximate delta using finite differences
    // This is a simplified approach for demonstration
    result_ = 0.0; // Placeholder - in a real implementation, this would be computed properly
}

void DeltaVisitor::visit(const ZeroCouponBond& bond) {
    // Delta of a ZCB is 0 since it's a deterministic instrument
    result_ = 0.0;
}

void DeltaVisitor::visit(const Portfolio& portfolio) {
    double total = 0.0;
    for (const auto& pos : portfolio.positions()) {
        DeltaVisitor temp_visitor(market_);
        pos.item->accept(temp_visitor);
        total += temp_visitor.result() * pos.quantity;
    }
    result_ = total;
}

// JsonVisitor implementation
JsonVisitor::JsonVisitor() = default;

void JsonVisitor::visit(const EuropeanOption& option) {
    std::ostringstream oss;
    oss << "{\"type\":\"european\",\"strike\":" << option.strike() 
        << ",\"maturity\":" << option.maturity() 
        << ",\"call\":" << (option.is_call() ? "true" : "false") << "}";
    result_ = oss.str();
}

void JsonVisitor::visit(const DigitalOption& option) {
    std::ostringstream oss;
    oss << "{\"type\":\"digital\",\"strike\":" << option.strike() 
        << ",\"maturity\":" << option.maturity() 
        << ",\"cash\":" << option.cash() << "}";
    result_ = oss.str();
}

void JsonVisitor::visit(const BarrierOption& option) {
    std::ostringstream oss;
    oss << "{\"type\":\"barrier\",\"strike\":" << option.strike() 
        << ",\"barrier\":" << option.barrier() 
        << ",\"maturity\":" << option.maturity() << "}";
    result_ = oss.str();
}

void JsonVisitor::visit(const ZeroCouponBond& bond) {
    std::ostringstream oss;
    oss << "{\"type\":\"zcb\",\"maturity\":" << bond.maturity() 
        << ",\"notional\":" << bond.notional() << "}";
    result_ = oss.str();
}

void JsonVisitor::visit(const Portfolio& portfolio) {
    std::ostringstream oss;
    oss << "{\"type\":\"portfolio\",\"positions\":[";
    for (size_t i = 0; i < portfolio.positions().size(); ++i) {
        if (i > 0) oss << ",";
        JsonVisitor temp_visitor;
        portfolio.positions()[i].item->accept(temp_visitor);
        oss << "{\"quantity\":" << portfolio.positions()[i].quantity 
            << ",\"item\":" << temp_visitor.result() << "}";
    }
    oss << "]}";
    result_ = oss.str();
}

} // namespace inst

